<!doctype html><html lang="fa" dir="rtl"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{{ $event->title }} | سینماپلاس</title><link rel="stylesheet" href="/css/cinema.css"></head><body><header class="nav"><a class="brand" href="/">سینما<span>پلاس</span></a><a class="ghost" href="/">بازگشت</a></header><main class="container"><section class="event-head"><div class="poster big">{{ $event->title }}</div><div><span class="eyebrow">{{ $event->category?->name }}</span><h1>{{ $event->title }}</h1><p>{{ $event->summary }}</p><div class="chips"><span>{{ $event->duration }} دقیقه</span><span>{{ $event->age_rating ?: '+۱۲' }}</span><span>{{ $event->director ?: 'کارگردان' }}</span></div><p class="muted">{{ $event->description }}</p><p class="muted">بازیگران: {{ $event->cast ?: 'اطلاعات ثبت نشده' }}<br>کشور: {{ $event->country ?: 'ایران' }} · زبان: {{ $event->language ?: 'فارسی' }}</p></div></section>@if($event->getFirstMediaUrl('poster'))<img src="{{ $event->getFirstMediaUrl('poster') }}" alt="پوستر {{ $event->title }}" style="max-width:260px;border-radius:16px;margin-bottom:25px">@endif @if($event->getMedia('gallery')->count())<h2>گالری تصاویر</h2><div class="grid" style="margin-bottom:35px">@foreach($event->getMedia('gallery') as $media)<img src="{{ $media->getUrl() }}" alt="{{ $event->title }}" style="width:100%;height:220px;object-fit:cover;border-radius:14px">@endforeach</div>@endif @if($event->getFirstMediaUrl('trailer'))<video controls style="max-width:100%;border-radius:16px;margin-bottom:35px"><source src="{{ $event->getFirstMediaUrl('trailer') }}"></video>@endif<h2>سانس‌های قابل خرید</h2><div class="show-grid">@forelse($shows as $show)<a class="show-card" href="{{ route('booking.seats',$show) }}"><strong>{{ jdate($show->starts_at)->format('%A %d %B') }}</strong><b>{{ $show->starts_at->format('H:i') }}</b><span>{{ $show->venue->name }}</span><small>{{ number_format($show->price) }} تومان</small></a>@empty<p>سانس فعالی برای این اثر وجود ندارد.</p>@endforelse</div></main></body></html>
